def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    # Find background (most frequent)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find marker and pattern colors (not background)
    non_bg = [c for c in counts.keys() if c != bg]
    if len(non_bg) < 2:
        return output

    # Determine which is marker vs pattern based on frequency and clustering
    # In this task: marker is less frequent, pattern forms cluster around marker
    other_order = sorted(non_bg, key=lambda c: counts[c])
    pattern_color = other_order[1]  # more frequent non-bg
    marker_color = other_order[0]   # less frequent

    # Find marker positions
    markers = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == marker_color:
                markers.append((r, c))

    # Find pattern cells relative to each marker
    pattern_to_marker = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == pattern_color:
                for mr, mc in markers:
                    dr, dc = r - mr, c - mc
                    # If within distance 3, this pattern cell belongs to this marker
                    if max(abs(dr), abs(dc)) <= 3:
                        if (mr, mc) not in pattern_to_marker:
                            pattern_to_marker[(mr, mc)] = set()
                        pattern_to_marker[(mr, mc)].add((dr, dc))

    # Find which markers have patterns (source markers)
    has_pattern = set()
    combined_pattern = set()

    for mk, cells in pattern_to_marker.items():
        if cells:
            has_pattern.add(mk)
            combined_pattern.update(cells)

    # If no markers have patterns, copy anyway using the pattern from sources
    if not has_pattern:
        return output

    # Apply pattern to ALL markers (preserve existing, add missing)
    for mr, mc in markers:
        for dr, dc in combined_pattern:
            nr, nc = mr + dr, mc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                output[nr][nc] = pattern_color

    return output
